#include "core/desktop_presets.hpp"
#include <iostream>
#include <stdexcept>
using namespace aether;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
int main(){try{Config base;base.hideTaskbar=false;base.reduceMotion=true;base.pins={{"Keep", "C:/keep.exe","keep","C:/my.png",17}};base.displays["second"].monitorOnly=false;auto presets=desktopPresets();check(presets.size()==6,"Six coordinated presets required");for(int n=0;n<6;++n){auto next=desktopPresetConfig(base,n);check(next.theme.name==presets[n].name&&next.iconPack==presets[n].iconPack&&next.widgetsLocked,"Preset recipe incomplete");check(next.hideTaskbar==base.hideTaskbar&&next.reduceMotion==base.reduceMotion&&next.pins==base.pins&&!next.displays.at("second").monitorOnly,"Preset overwrote recovery, app overrides or monitor filtering");auto reload=parseSettings(serializeSettings(next));check(reload.iconPack==next.iconPack&&reload.widgetsLocked&&reload.theme==next.theme,"Preset config did not round trip");check(presets[n].background>=0&&presets[n].background<=9,"Preset wallpaper out of bounds");}auto legacy=parseSettings("");check(legacy.widgetsLocked&&legacy.widgetGrid==12&&legacy.iconPack.empty(),"Legacy widgets must start locked with native icons");base.widgetGrid=24;base.widgetsLocked=false;base.iconPack="papirus-neon";auto reload=parseSettings(serializeSettings(base));check(!reload.widgetsLocked&&reload.widgetGrid==24&&reload.iconPack==base.iconPack,"Layout editing settings not persisted");check(parseSettings("[behavior]\niconPack=../../bad\nwidgetGrid=999\n").iconPack.empty(),"Pack traversal not rejected");std::cout<<"PASS six presets, preserved recovery/pins, legacy lock defaults and persisted selection\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
